INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-chunqiu','晋','["晋","晋国"]',NULL,'cn','east_asia',-1042,1,NULL,'year',-349,12,NULL,'month',-12492,-4165,'ochre',NULL,NULL,'周成王封叔虞于唐，其子燮继位后改国号为晋。曲村—天马遗址为西周时期晋国早期都邑，发现连续的晋侯及夫人墓葬；早期都邑与文献所称翼的对应、唐至晋的迁移过程及始用年代仍有争议。昭侯时晋君都翼，曲沃支系与翼公室争位，前678年曲沃武公代翼。献公时都绛，景公前585年迁新田。前403年三家分晋；前376年公室被废、另立傀儡君，前349年静公被杀而国亡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-chonger','重耳','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋文公（重耳），晋献公之子。流亡十九年后即位，城濮之战败楚，践土会盟，列为春秋五霸之一。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋文公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','文公',NULL,'晋文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-shuyu','虞','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周武王之子、成王之弟，称唐叔虞。周初平定唐地后受封于唐，为晋国君统的开端；其子燮继位后以晋为号。桐叶封弟是后世传说，不能据此确认实际分封过程。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/唐叔虞"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'唐叔虞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r1','燮','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，唐叔虞之子，继承晋君之位；传世文献记载简略，具体在位年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燮"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'燮','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r10','仇','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋文侯（仇），穆侯太子，前780–前746年在位。助周平王东迁，周室赐弓矢，晋国始强盛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋文侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','文侯',NULL,'晋文侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r11','伯','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋昭侯（伯），文侯之子，前745–前740年在位。筑曲沃城封叔父成师，曲沃坐大之始。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋昭侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','昭侯',NULL,'晋昭侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r12','成师','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曲沃桓叔（成师），穆侯少子，曲沃第一代君主，前744–前731年在位。封于曲沃，渐与晋都翼城抗衡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃桓叔"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"王恩田：《“曲沃叛王”与晋公戈年代》（桓、庄、武均为谥称）","url":"https://www.fdgwz.org.cn/Web/Show/2458"}]','桓叔',NULL,'曲沃桓叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r13','平','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋孝侯（平），昭侯之子，前739–前724年在位。被曲沃庄伯派人刺杀，曲沃代翼之争加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋孝侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','孝侯',NULL,'晋孝侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r14','鱓','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曲沃庄伯（鱓），桓叔之子，前730–前716年在位。弑孝侯，晋鄂侯出兵反击未成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃庄伯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"王恩田：《“曲沃叛王”与晋公戈年代》（桓、庄、武均为谥称）","url":"https://www.fdgwz.org.cn/Web/Show/2458"}]','庄伯',NULL,'曲沃庄伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r15','却','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋鄂侯（却），孝侯之弟，前723–前718年在位。连年抵御曲沃庄伯，终为庄伯所弑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋鄂侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','鄂侯',NULL,'晋鄂侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r16','光','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋哀侯（光），鄂侯之子，前717–前709年在位。为曲沃武公派人刺杀于宫阙之下。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋哀侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','哀侯',NULL,'晋哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r17','称','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，曲沃庄伯之子，名称。前715年继父为曲沃君，延续曲沃与翼城公室的争位；前678年灭晋侯缗、并有晋地，受周王册命为晋君，前677年去世，子诡诸继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曲沃武公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"《左传·庄公十六年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/zhuang-gong-shi-liu-nian/zhs"}]','武公',NULL,'曲沃武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r18','','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，哀侯之子，史称小子侯，个人名失载。前708年继位，前705年为曲沃武公所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋小子侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','小子侯',NULL,'晋小子侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r19','缗','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名缗，晋侯。曲沃武公攻杀小子侯后，晋人立哀侯之弟于翼，是为缗；前678年为曲沃武公所灭，曲沃并晋。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/缗"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"},{"label":"《左传·庄公十六年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/zhuang-gong-shi-liu-nian/zhs"}]',NULL,NULL,'缗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r2','宁族','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，燮之子，名宁族，谥武侯。继父燮为晋君；其后由成侯服人继位。传世文献对其事迹与在位年代记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋武侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','武侯',NULL,'晋武侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r20','诡诸','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献公（诡诸），曲沃武公之子，前676–前651年在位。灭桓庄之族、骊姬之乱，并国十七服国三十八。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋献公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','献公',NULL,'晋献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r21','夷吾','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋惠公（夷吾），献公之子，骊姬所生，前650–前637年在位。靠秦穆公回国即位，后与秦战于韩失国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋惠公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','惠公',NULL,'晋惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r22','圉','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋怀公（圉），惠公之子，前637年在位。趁重耳在秦欲继位，秦送重耳回国，怀公被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋怀公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','怀公',NULL,'晋怀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r24','欢','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋襄公（欢），文公之子，前627–前621年在位。破秦救周，殽山败秦师，维持晋国霸业。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋襄公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','襄公',NULL,'晋襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r25','夷皋','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋灵公（夷皋），襄公之子，前620–前607年在位。荒淫用佞，赵盾屡谏不果，后为赵穿所弑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋灵公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','灵公',NULL,'晋灵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r26','黑臀','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋成公（黑臀），文公少母弟，前606–前600年在位。灵公被杀后赵氏拥立，寻讨弑灵公之罪。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋成公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','成公',NULL,'晋成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r27','据','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋景公（据），成公之子，前599–前581年在位。灭赵氏，邲之战败楚，但六卿势力日盛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋景公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','景公',NULL,'晋景公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r28','寿曼','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋厉公（寿曼），景公之子，前580–前573年在位。欲集权削六卿，为栾书、中行氏弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋厉公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','厉公',NULL,'晋厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r29','周','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋悼公（周），襄公曾孙，前572–前558年在位。年少即位却整饬六卿，九合诸侯，晋国复振。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋悼公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','悼公',NULL,'晋悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r3','服人','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名服人，承袭武侯为晋君。传世文献主要保存其世系，事迹与具体在位年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋成侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','成侯',NULL,'晋成侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r30','彪','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋平公（彪），悼公之子，前557–前532年在位。会诸侯于平丘，又弭兵于宋，霸业犹存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋平公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','平公',NULL,'晋平公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r31','夷','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋昭公（夷），平公之子，前531–前526年在位。六卿专权加剧，昭公终死于饥贫。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋昭公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','昭公',NULL,'晋昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r32','弃疾','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋顷公（弃疾），昭公之子，前525–前512年在位。诛伯昏咎等大夫，加速六卿兼并。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋顷公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','顷公',NULL,'晋顷公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r33','午','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋定公（午），顷公之子，前511–前475年在位。赵襄子灭智氏，前453年韩赵魏共灭智伯，三家分晋前奏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋定公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','定公',NULL,'晋定公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r34','凿','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋出公（凿），定公之子，前474–前452年在位。欲讨伐韩赵魏反被逼迁，死于齐。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋出公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','出公',NULL,'晋出公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r35','骄','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋哀公（骄），出公之后，前451–前434年在位。韩赵魏瓜分晋剩余公室土地，君主名存实亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋哀公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','哀公',NULL,'晋哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r36','柳','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋幽公（柳），哀公之子，前433–前416年在位。正室地位为赵氏所废，政权益为傀儡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋幽公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','幽公',NULL,'晋幽公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r37','止','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋烈公（止），幽公之后，前415–前389年在位。三家分晋已成定局，烈公仅守附庸之位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋烈公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','烈公',NULL,'晋烈公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r38','颀','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋孝公（颀），烈公之后，前388–前357年在位。魏惠王会诸侯朝天子，孝公仅为陪臣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋孝公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','孝公',NULL,'晋孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r39','俱酒','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋静公（俱酒），孝公之子，前356–前349年在位。三家废晋静公，晋国六卿时代终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋静公"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','静公',NULL,'晋静公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r4','福','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名福，成侯之子，继位为晋君。北赵晋侯墓地及相关铭文研究为其名号与年代提供线索；传统编年记其卒于前859年，继位年份失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋厉侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','厉侯',NULL,'晋厉侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r5','宜臼','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋靖侯（宜臼），厉侯之子，前858–前841年在位。在位末年周厉王出奔，史称共和。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋靖侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','靖侯',NULL,'晋靖侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r6','司徒','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋釐侯（司徒），靖侯之子，前840–前823年在位。西周晋国君主，史书记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋釐侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','釐侯',NULL,'晋釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r7','籍','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献侯（籍），釐侯之子，前822–前812年在位。西周晋国世系君主，史书记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋献侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','献侯',NULL,'晋献侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r8','费','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋穆侯（费），献侯之子，前811–前785年在位。生太子仇与少子成师，酿成日后曲沃之乱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋穆侯"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','穆侯',NULL,'晋穆侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-r9','','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，穆侯之弟，谥殇叔，个人名失载。穆侯死后取代太子仇为君；前781年文侯仇复位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晋殇叔"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]','殇叔',NULL,'晋殇叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-xi-qi','奚齐','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献公与骊姬之子。献公病重时受命由荀息辅佐；献公死后，荀息拥立他继位，前651年在献公丧所被里克杀害，未能逾年。','[{"label":"《左传·僖公九年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/xi-gong-jiu-nian/zhs"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'奚齐','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jin-zhuo-zi','卓子','jin-chunqiu','[]','姬','晋',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','晋献公之子。奚齐被杀后，荀息拥立公子卓以完成献公安葬；前651年周历十一月为里克所杀，荀息亦死。史籍未载其独立谥号。','[{"label":"《左传·僖公九年》","url":"https://ctext.org/chun-qiu-zuo-zhuan/xi-gong-jiu-nian/zhs"},{"label":"《史记·晋世家》","url":"https://zh.wikisource.org/wiki/史記/卷039"}]',NULL,NULL,'卓子','[]');
